void ov01_021F3F50(SaveInfo *saveInfo, const FieldSystem *fieldSystem) {
    SaveData *saveData = fieldSystem->saveData;
    Location *curLocation = LocalFieldData_GetCurrentPosition(Save_LocalFieldData_Get(saveData));
    Pokedex *pokedex = Save_Pokedex_Get(saveData);

    saveInfo->mapLabelTextID = MapHeader_GetMapSec(curLocation->mapHeaderID);

    if (Pokedex_IsEnabled(pokedex)) {
        saveInfo->pokedexCount = Pokedex_CountDexOwned(pokedex);
    } else {
        saveInfo->pokedexCount = 0;
    }

    saveInfo->trainerInfo = Save_PlayerData_GetProfile(saveData);
    saveInfo->playTime = Save_PlayerData_GetIGTAddr(saveData);
}
